// ── Runtime polymorphism: method overriding ────────────────────────────────
class Animal {
    // Parent defines the method
    void speak() {
        System.out.println("Some generic animal sound");
    }
}

class Dog extends Animal {
    @Override
    void speak() { System.out.println("Woof!"); }  // child overrides
}

class Cat extends Animal {
    @Override
    void speak() { System.out.println("Meow!"); }  // child overrides
}

// ── Compile-time polymorphism: method overloading ──────────────────────────
class Calculator {
    // Same name, different parameter types — compiler picks at compile time
    int add(int a, int b)          { return a + b; }
    double add(double a, double b) { return a + b; }
    int add(int a, int b, int c)   { return a + b + c; }
}

public class PolymorphismDemo {
    public static void main(String[] args) {
        // Runtime polymorphism — JVM looks at actual object at runtime
        Animal a1 = new Dog();  // Animal reference, Dog object
        Animal a2 = new Cat();  // Animal reference, Cat object
        a1.speak();             // Output: Woof!   ← JVM chose Dog.speak()
        a2.speak();             // Output: Meow!   ← JVM chose Cat.speak()

        // Compile-time polymorphism — compiler picks from argument types
        Calculator calc = new Calculator();
        System.out.println(calc.add(2, 3));       // Output: 5   ← int version
        System.out.println(calc.add(2.5, 3.5));   // Output: 6.0 ← double version
        System.out.println(calc.add(1, 2, 3));    // Output: 6   ← 3-arg version
    }
}
// Output:
// Woof!
// Meow!
// 5
// 6.0
// 6
