```java
class Animal {
    void speak() {
        System.out.println("Some generic animal sound");
    }
}

class Dog extends Animal {
    @Override
    void speak() { System.out.println("Woof!"); }
}

class Cat extends Animal {
    @Override
    void speak() { System.out.println("Meow!"); }
}

public class RuntimePolymorphismDemo {

    // This method accepts ANY Animal — it doesn't care about the actual subtype
    static void makeAnimalSpeak(Animal a) {
        a.speak(); // JVM dispatches to the actual object's speak() at runtime
    }

    public static void main(String[] args) {
        Animal a1 = new Dog();  // Animal reference → Dog object
        Animal a2 = new Cat();  // Animal reference → Cat object
        Animal a3 = new Animal(); // Animal reference → Animal object

        a1.speak();  // Output: Woof!  ← JVM found Dog.speak()
        a2.speak();  // Output: Meow!  ← JVM found Cat.speak()
        a3.speak();  // Output: Some generic animal sound

        System.out.println("--- via helper method ---");
        makeAnimalSpeak(new Dog()); // Output: Woof!
        makeAnimalSpeak(new Cat()); // Output: Meow!
        // makeAnimalSpeak never changes when you add Snake, Bird, etc.

        // Compile-time restriction: reference type controls visibility
        // a1.wagTail(); // COMPILE ERROR — Animal has no wagTail()
    }
}
// Output:
// Woof!
// Meow!
// Some generic animal sound
// --- via helper method ---
// Woof!
// Meow!
