class Logger {
    // ── Valid overloads — parameter lists differ ──────────────────────────────

    // 1. Different number of parameters
    void log(String message) {
        System.out.println("[INFO] " + message);
    }

    void log(String message, int level) {
        System.out.println("[LEVEL " + level + "] " + message);
    }

    // 2. Different parameter types
    void log(int code) {
        System.out.println("[CODE] " + code);
    }

    void log(double metric) {
        System.out.println("[METRIC] " + metric);
    }

    // 3. Different parameter order
    void log(String message, double value) {
        System.out.println(message + ": " + value);
    }

    void log(double value, String message) {
        System.out.println(value + " — " + message);
    }

    // ── INVALID — return type alone cannot distinguish overloads ──────────────
    // String log(String message) { return message; }  // COMPILE ERROR:
    // 'log(String)' is already defined — same parameter list as void log(String)
}

public class OverloadingDemo {
    public static void main(String[] args) {
        Logger logger = new Logger();

        logger.log("Server started");           // picks log(String)
        logger.log("Auth failed", 3);           // picks log(String, int)
        logger.log(404);                        // picks log(int)
        logger.log(3.14);                       // picks log(double) — auto-widens float if needed
        logger.log("Response time", 0.42);      // picks log(String, double)
    }
}
// Output:
// [INFO] Server started
// [LEVEL 3] Auth failed
// [CODE] 404
// [METRIC] 3.14
// Response time: 0.42
