class Animal {
    // Base method: protected, returns Animal, throws Exception
    protected Animal reproduce() throws Exception {
        return new Animal();
    }

    public String speak() {
        return "...";
    }

    public final void breathe() {
        System.out.println("Breathing");
    }
}

class Dog extends Animal {

    // ── VALID overrides ────────────────────────────────────────────────────

    @Override
    public Dog reproduce() throws IllegalStateException {
        // public is MORE permissive than protected — valid (Rule 3)
        // Dog is covariant subtype of Animal — valid return type (Rule 2)
        // IllegalStateException is unchecked — unchecked exceptions are not restricted (Rule 4)
        return new Dog();
    }

    @Override
    public String speak() {
        return "Woof!"; // same signature, same return type — valid (Rules 1 & 2)
    }

    // ── INVALID overrides (commented out — would not compile) ──────────────

    // @Override
    // private String speak() { return "Woof!"; }  // ERROR: narrowing access public→private (Rule 3)

    // @Override
    // public void breathe() { }  // ERROR: cannot override final method (Rule 5)

    // @Override
    // protected Animal reproduce() throws Exception { return new Dog(); } // ERROR if we tried to throw
    // a checked exception not declared in parent — see Rule 4
}

public class OverridingDemo {
    public static void main(String[] args) throws Exception {
        Animal a = new Dog();                  // parent reference, child object
        System.out.println(a.speak());         // Output: Woof!  ← Dog.speak() via dynamic dispatch
        System.out.println(a.reproduce());     // Output: Dog@...  ← Dog.reproduce() at runtime
    }
}
// Output:
// Woof!
// Dog@<hashcode>
